use chrono::Utc;

use crate::connection::LocalFilesDbConnection;
use crate::error::LocalFilesDbError;
use crate::thumbnail_state::ThumbnailState;

pub struct SetThumbnailResultArgs<'a> {
  pub db: &'a LocalFilesDbConnection,
  pub file_path: &'a str,
  pub state: ThumbnailState,
  /// The generator that produced this outcome; rows below the current
  /// version are regenerated by the worker.
  pub generator_version: i64,
  /// Absolute cache path of the static jpg, when it was written.
  pub maybe_thumbnail_jpg_path: Option<&'a str>,
  /// Absolute cache path of the animated webp, when it was written.
  pub maybe_animated_preview_webp_path: Option<&'a str>,
  /// Why generation failed (or was unsupported); cleared on success.
  pub maybe_error: Option<&'a str>,
}

/// Record the outcome of one generation attempt for a path. Every call
/// counts as an attempt. Returns whether a row was updated (there is no row
/// until the file has been hashed).
pub async fn set_thumbnail_result(args: SetThumbnailResultArgs<'_>) -> Result<bool, LocalFilesDbError> {
  let now = Utc::now();
  let result = sqlx::query(
    r#"
    UPDATE local_files
    SET
      thumbnail_state = ?2,
      thumbnail_attempts = thumbnail_attempts + 1,
      thumbnail_last_error = ?3,
      thumbnail_jpg_path = ?4,
      animated_preview_webp_path = ?5,
      has_thumbnail = ?6,
      has_animated_preview = ?7,
      thumbnail_updated_at = ?8,
      updated_at = ?8,
      thumbnail_generator_version = ?9
    WHERE file_path = ?1
    "#,
  )
      .bind(args.file_path)
      .bind(args.state.to_str())
      .bind(args.maybe_error)
      .bind(args.maybe_thumbnail_jpg_path)
      .bind(args.maybe_animated_preview_webp_path)
      .bind(args.maybe_thumbnail_jpg_path.is_some())
      .bind(args.maybe_animated_preview_webp_path.is_some())
      .bind(now)
      .bind(args.generator_version)
      .execute(args.db.get_pool())
      .await?;
  Ok(result.rows_affected() > 0)
}
